def enrich(cards):
    rows={}
    for line in PROMPTS.strip().splitlines():
        ident,omen,task,choice=line.split('|')
        assert ident not in rows,ident
        rows[ident]=dict(omen=omen,task=task,choice=choice,kind='Авторская личная трактовка — не цитата из книги',basis='Образ карты: Проклятье Страда, приложение Е. Метод личного задания и загадочной подсказки: Повышение ставок, PDF 9–10.')
    assert set(rows)=={c['id'] for c in cards},set(rows)^{c['id'] for c in cards}
    for c in cards:
        c['personal']=rows[c['id']]
        if c['id'] in DRAFTS:c['personal']['campaignDraft']=DRAFTS[c['id']]
        if c['id']=='high-2':c['personal']['raisingExample']='В «Повышении ставок» карта Зверя прямо предложена как подходящий образ задания об оборотнях (PDF 9). Текста готового личного предсказания для этой карты там нет.'
        if c['id']=='swords-1':c['personal']['raisingExample']='В «Повышении ставок» Мститель прямо назван подходящей картой задания паладина (PDF 9). Это пример соответствия темы карте, а не требование выдавать её каждому паладину.'
